#include <bits/stdc++.h>
using namespace std;
int main() {
  ios::sync_with_stdio(false); cin.tie(nullptr);
  string s; cin >> s;
  // 9^18 does not fit in 64 bits, so multiply in a digit vector (big number)
  vector<int> num(1, 1);
  for (char c : s) { int d = c - '0'; int carry = 0;
    for (auto &x : num) { int v = x * d + carry; x = v % 10; carry = v / 10; }
    while (carry) { num.push_back(carry % 10); carry /= 10; } }
  while (num.size() > 1 && num.back() == 0) num.pop_back();
  for (int i = (int)num.size() - 1; i >= 0; i--) cout << num[i];
  cout << "\n";
  return 0;
}

