import java.util.*;
import java.io.*;
public class Main {
  public static void main(String[] args) throws IOException {
    String[] t = new String(System.in.readAllBytes()).trim().split("\\s+");
    int p = 0;
    int m = Integer.parseInt(t[p++]), s = Integer.parseInt(t[p++]);
    if (s == 0) { System.out.println(m == 1 ? "0" : "-1"); return; }
    if (s > 9 * m) { System.out.println(-1); return; }
    int[] d = new int[m]; int rest = s - 1;
    for (int i = m - 1; i > 0; i--) { d[i] = Math.min(9, rest); rest -= d[i]; }
    d[0] = rest + 1;
    StringBuilder sb = new StringBuilder(); for (int x : d) sb.append(x);
    System.out.println(sb);
  }
}

